public class Logger {
    private static String log = "Start";

    public void appendLog(String msg) {
        log.concat(msg);
    }

    public void updateLog(String msg) {
        log += msg;
    }

    public static void main(String[] args) {
        Logger l1 = new Logger();
        Logger l2 = new Logger();

        l1.appendLog("-Init");
        l2.updateLog("-Run");

        System.out.print(Logger.log);
    }
}

public class Time2 {
    private int hour, minute;

    public Time2() {
        this(25, 0);
        System.out.print("A");
    }

    public Time2(int hour, int minute) {
        if (hour >= 24) {
            throw new IllegalArgumentException("Bad hour");
        }
        this.hour = hour;
        this.minute = minute;
        System.out.print("B");
    }

    public static void main(String[] args) {
        try {
            Time2 t = new Time2();
            System.out.print("C");
        } catch (IllegalArgumentException e) {
            System.out.print("D");
        }
    }
}
